Föremålets ansträngning = {"C08": 41, "C55": 28, "A43": 11, "A67": 806, "B42": 948, "A62": 303, "B19": 744, "C43": 611, "C73": 328, "C10": 461, "B36": 401, "A18": 321, "C61": 409, "C67": 65, "C42": 66, "C70": 936, "B40": 325, "C39": 994, "A21": 616, "C16": 994}

